<script setup lang="ts">
import {ref,computed,watch} from 'vue';import {useRouter,useRoute} from 'vue-router';import {auth,signOut} from '@/stores/auth';
const menu=ref(false),router=useRouter(),route=useRoute();const dashboard=computed(()=>auth.user?.role==='admin'?'/admin':auth.user?.role==='instructor'?'/instructor':'/account');
function logout(){signOut();router.push('/')}watch(()=>route.fullPath,()=>{menu.value=false;setTimeout(()=>{if(route.hash)document.querySelector(route.hash)?.scrollIntoView({behavior:'smooth'});else window.scrollTo(0,0)},50)})
</script>
<template><div class="page"><header class="header container"><div class="header__bar"><RouterLink to="/" class="logo">MONTIS</RouterLink><button class="burger" @click="menu=!menu" aria-label="Открыть меню"><span></span><span></span><span></span></button><nav class="header__nav" :class="{'nav-open':menu}"><RouterLink class="header__link" to="/lessons">Занятия</RouterLink><RouterLink class="header__link" to="/rental">Прокат</RouterLink><RouterLink class="header__link" to="/#instructors">Инструкторы</RouterLink><RouterLink class="header__link" to="/#about">О курорте</RouterLink><RouterLink class="header__link" to="/#contacts">Контакты</RouterLink></nav><div class="header__actions"><RouterLink v-if="!auth.user" class="btn btn--primary" to="/login">Войти</RouterLink><template v-else><RouterLink class="btn btn--light" :to="dashboard">{{auth.user.name?.split(' ')[0]||'Кабинет'}}</RouterLink><button class="btn btn--outline btn--sm" @click="logout">Выйти</button></template></div></div></header><main class="page__main"><RouterView/></main><div class="container"><footer class="footer"><div class="footer__grid"><div class="footer__contacts"><div class="footer__label">Email</div><a class="footer__email" href="mailto:info@montis.ru">info@montis.ru</a><div class="footer__label">Адрес</div><div class="footer__address">Красная Поляна,<br/>ул. Горная, 15</div></div><div class="footer__col"><div class="footer__heading">Занятия</div><RouterLink to="/lessons?category=ski">Горные лыжи</RouterLink><RouterLink to="/lessons?category=snowboard">Сноуборд</RouterLink><RouterLink to="/lessons?category=individual">Индивидуальное обучение</RouterLink></div><div class="footer__col"><div class="footer__heading">Клиентам</div><RouterLink to="/rental">Прокат оборудования</RouterLink><RouterLink to="/#instructors">Инструкторы</RouterLink><RouterLink to="/account">Личный кабинет</RouterLink></div></div><div class="footer__wordmark">Montis</div></footer></div></div></template>
